 std::ofstream detail(out/"actual_operator_derivatives.jsonl");std::size_t tested=0,failed=0,same_cell_FD=0,branch_changed=0,FD_failed=0,original_W_cross_units=0;double max_primal=0,max_IFT=0,max_FD=0;Json protected_point;auto native_cell=[&](std::size_t raw,double station){const auto&o=formal->core.packet.rows[raw];const auto&p=formal->core.model.materials[o.material].paths[o.path];if(p.points.size()>1)return int(std::min(p.points.size()-2,std::size_t(std::max(0.,std::floor(station*(p.points.size()-1))))));return 0;};auto query_cell=[&](std::size_t raw,double alpha){const auto&q=*formal->core.packet.rows[raw].query;if(!q.den.empty())return 0;auto it=std::upper_bound(q.alpha.begin(),q.alpha.end(),alpha);return int(it==q.alpha.end()?q.alpha.size()-2:std::size_t(it-q.alpha.begin()-1));};
