 for(const auto&unit:units){bool cross=false;const auto n=unit.group.rows.size();if(n>1&&!unit.unknown_engineering){for(std::size_t k=0;k<unit.group.rank&&!cross;++k){int blocks=0;for(std::size_t j=0;j<n;++j)blocks+=unit.group.W[k*2*n+2*j]!=0||unit.group.W[k*2*n+2*j+1]!=0;cross|=blocks>1;}}if(cross){++original_W_cross_units;audit(unit,"actual_original_whole_W_with_cross_terms");}auto it=std::find(unit.group.rows.begin(),unit.group.rows.end(),std::size_t(197653));if(it!=unit.group.rows.end()){auto local=std::size_t(it-unit.group.rows.begin());const auto&o=formal->core.packet.rows[197653];double trace=0;for(std::size_t k=0;k<unit.group.rank;++k)for(int c=0;c<2;++c){const double a=unit.group.W[k*2*n+2*local+c];trace+=a*a;}protected_point={{"raw_index",197653},{"source_row_id",o.source_row_id},{"native_pts",o.pts},{"kind",o.kind},{"original_source_UV",o.uv},{"existing_per_source_engineering_budget",weights[197653]},{"original_E_px",o.E},{"actual_2D_information_trace",trace},{"target_2D_information_trace",2*weights[197653]/(o.E*o.E)},{"noise_calibration_claimed",false},{"normal_profile_rows_can_dilute_this_budget",false}};audit(unit,"actual_protected_fixed_2D_anchor_full_unit");}}
